PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL,terms_version TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE consent_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,terms_version TEXT NOT NULL,training INTEGER NOT NULL,sale INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,registration TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX challenges_email ON challenges(email,created_at);
CREATE TABLE uploads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,object_key TEXT UNIQUE NOT NULL,filename TEXT NOT NULL,size INTEGER NOT NULL,created_at INTEGER NOT NULL);
